<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import type {AppointmentSummary} from '../../api/workspace-types'
import {useUnsaved} from '../../composables/useUnsaved'
import WorkspacePanel from '../../components/WorkspacePanel.vue'
import {useRoute,useRouter} from 'vue-router'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
import {useViewScope} from '../../stores/view-scope'
import {useAuthenticationStore} from '../../stores/authentication'
type Context=Omit<components['schemas']['ClinicalContext'],'appointment'>&{appointment:AppointmentSummary};type Appointment=AppointmentSummary;type Catalog=components['schemas']['CatalogItem']
const auth=useAuthenticationStore(),route=useRoute(),router=useRouter(),api=createProtectedClient(),id=ref(typeof route.query.appointmentId==='string'?route.query.appointmentId:''),visits=ref<Appointment[]>([]),next=ref<string|null>(null),context=ref<Context|null>(null),etag=ref(''),notes=ref(''),catalog=ref<Catalog[]>([]),treatment=ref(''),units=ref('1.00'),performed=ref(new Date(Date.now()+8*3600000).toISOString().slice(0,19)),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref('')
const completion=ref(false),dirty=computed(()=>!!context.value&&notes.value!==(context.value.problems_or_special_needs??''))
const canLeave=useUnsaved(()=>dirty.value||!!treatment.value,()=>unknown.value)
let pending:PreparedCommand|undefined
const can=(cap:string)=>auth.canAccess('DENTIST',cap)
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({CLINICAL_RECORD_READ_ONLY:'当前就诊已进入只读阶段。',ACTUAL_TREATMENT_REQUIRED:'至少记录一项已实际实施的有效治疗后才能完成。',DENTIST_QUALIFICATION_UNAVAILABLE:'实施牙医治疗日的必需资质不满足。',INVALID_PERFORMED_TIME:'请核对实际实施时间，不能早于到诊或晚于服务器当前时间。'}[failure.code]??(failure.status===412?'资料已更新，请重新读取后核对。':`操作未完成：${failure.message}`)):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){context.value=null;visits.value=[];notes.value='';treatment.value='';await auth.ensure();await router.replace(auth.identity?'/':'/authentication')}}
async function load(){if(!id.value || pending)return;context.value=null;busy.value=true;error.value='';try{const response=await api.getResource<Context>(`/api/v1/appointments/${encodeURIComponent(id.value)}/clinical-context`);context.value=response.data;etag.value=response.etag??'';notes.value=response.data.problems_or_special_needs??''}catch(failure){context.value=null;await failed(failure)}finally{busy.value=false}}
let listVersion=0
const listBusy=ref(false)
const scope=useViewScope();watch(()=>scope.clinic,()=>{visits.value=[];next.value=null;list()})
async function list(more=false){if(!can('listAppointments'))return;const version=++listVersion;listBusy.value=true;if(!more){visits.value=[];next.value=null}try{const query=new URLSearchParams({role:'DENTIST',status:'IN_PROGRESS',limit:'100'});if(scope.clinic)query.set('clinic_id',scope.clinic);if(more && next.value)query.set('cursor',next.value);const page=await api.get<{items:Appointment[];next_cursor:string|null}>(`/api/v1/workspace/appointments?${query}`);if(version!==listVersion)return;visits.value=more?[...visits.value,...page.items]:page.items;next.value=page.next_cursor}catch(failure){if(version===listVersion)await failed(failure)}finally{if(version===listVersion)listBusy.value=false}}
async function locate(){if(canLeave())await load()}
async function choose(visit:Appointment){if(pending||!canLeave())return;id.value=visit.appointment_id;await load()}
async function execute(){if(!pending)return;busy.value=true;error.value='';const operation=pending.operation;try{const response=await api.execute<components['schemas']['AppliedTreatmentView']|Appointment>(pending);notice.value=operation==='recordAppliedTreatment'?`实际治疗已保存：${(response.data as components['schemas']['AppliedTreatmentView']).applied_treatment_id}`:operation==='completeAppointment'?'本次诊疗已完成，治疗记录进入只读阶段。':'问题及特殊需求已保存。';pending=undefined;unknown.value=false;completion.value=false;if(operation==='recordAppliedTreatment')treatment.value='';await load();await list()}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function record(){if(pending)return;if(dirty.value){error.value='请先保存问题与特殊需求，再添加治疗项目。';return;}pending=prepareCommand('recordAppliedTreatment','POST',`/api/v1/appointments/${id.value}/applied-treatments`,{treatment_id:treatment.value,standard_units:units.value,performed_at:performed.value+'+08:00'});await execute()}
async function saveNotes(){if(pending)return;pending=prepareCommand('updateClinicalNotes','PATCH',`/api/v1/appointments/${id.value}/clinical-notes`,{problems_or_special_needs:notes.value},etag.value);await execute()}
async function complete(){if(pending||dirty.value||treatment.value)return;pending=prepareCommand('completeAppointment','POST',`/api/v1/appointments/${id.value}/complete`,{});await execute()}
async function query(){if(!pending)return;try{const receipt=await api.requestResult<{status:string}>(pending);notice.value=receipt.status==='SUCCEEDED'?'原请求已成功，请重新确认取得当前授权结果。':'尚未确认成功，请保留当前页面。'}catch(failure){await failed(failure)}}
onMounted(async()=>{try{let cursor:string|null=null;do{const page:{items:Catalog[];next_cursor:string|null}=await api.get(`/api/v1/treatments?limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`);catalog.value.push(...page.items);cursor=page.next_cursor}while(cursor);await list();if(id.value)await load()}catch(failure){await failed(failure)}})
</script>
<template><section><p class="eyebrow">CLINICAL WORKSPACE</p><h1>诊疗工作区</h1><p>记录本人实际实施的项目；按治疗日核验资质和执业，并保存当时目录价格。</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询办理进度</button><button :disabled="busy" @click="execute">重新确认办理结果</button></div><section v-if="can('listAppointments') && !context" class="surface"><h2>当前授权诊所的进行中就诊</h2><p v-if="listBusy" role="status">正在读取就诊队列…</p><p v-else-if="!visits.length&&!error" class="empty-state">当前授权范围暂无进行中的就诊。</p><ul class="queue-list"><li v-for="visit in visits" :key="visit.appointment_id"><span><strong>{{visit.patient_name||'摘要未取得'}}</strong><small>{{visit.patient_number}} · {{visit.clinic_name}} · {{new Date(visit.scheduled_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small></span> <button :disabled="busy || unknown" @click="choose(visit)">接诊并查看必要风险</button></li></ul><button v-if="next" :disabled="busy || unknown" @click="list(true)">更多进行中就诊</button></section><details><summary>按预约标识定位其他就诊</summary><form @submit.prevent="locate"><fieldset :disabled="busy || unknown"><label>就诊预约 ID<input v-model="id" required pattern="[1-9][0-9]*"></label><button>读取当前就诊</button></fieldset></form></details>
<section v-if="context" class="clinical-workspace"><div class="patient-summary"><div><h2>{{context.appointment.patient_name||'当前患者'}}</h2><small>{{context.appointment.patient_number}} · {{context.appointment.clinic_name}} · {{context.appointment.dentist_name}}</small></div><button :disabled="busy||unknown" @click="if(canLeave()){context=null;id='';treatment=''}">← 返回就诊列表</button><span class="status-badge">{{context.appointment.status==='IN_PROGRESS'?'诊疗中':'只读记录'}}</span></div><aside class="surface clinical-next"><h2>本次就诊摘要</h2><div class="task-row"><span>当前阶段</span><strong>{{context.appointment.status==='IN_PROGRESS'?'诊疗中':'只读'}}</strong></div><div class="task-row"><span>实际治疗</span><strong>{{context.applied_treatments.length}} 项</strong></div><div class="task-row"><span>接诊医生</span><strong>{{context.appointment.dentist_name}}</strong></div><p>核对实际治疗和实施时间，完成后交接费用核对。</p><button v-if="can('completeAppointment')" class="compact-primary" :disabled="busy||unknown||dirty||!!treatment||!context.applied_treatments.length||context.appointment.status!=='IN_PROGRESS'" @click="completion=true">查看完成确认</button><p v-if="dirty||treatment" role="status">请先保存当前修改。</p></aside><div :class="['risk-banner',{'risk-recorded':context.patient_allergy_review_status==='RECORDED','risk-clear':context.patient_allergy_review_status==='NO_KNOWN'}]"><h3>本次就诊风险与问题</h3><p>患者编号 {{context.appointment.patient_number}} · {{context.appointment.status==='IN_PROGRESS'?'诊疗中':context.appointment.status==='INVOICED'?'已生成费用凭据，只读':'已完成治疗，只读'}}</p><strong>{{context.patient_allergy_review_status==='NO_KNOWN'?'已核实无已知过敏':context.patient_allergy_review_status==='RECORDED'?'存在已记录过敏':'过敏资料尚未核实，请结合实际情况核实风险'}}</strong><p v-if="context.self_reported_allergies"><strong>本人初次填报（待医护复核）</strong>：{{context.self_reported_allergies}}</p><ul><li v-for="allergy in context.allergy_records.filter(a=>!a.is_retracted)" :key="allergy.allergy_id">{{allergy.allergy_name}} · {{allergy.severity_note || '未注明程度'}} · {{allergy.clinical_note || ''}}</li></ul></div>
<form v-if="can('updateClinicalNotes')" @submit.prevent="saveNotes"><fieldset :disabled="busy || unknown || context.appointment.status!=='IN_PROGRESS'"><label>问题与特殊需求<textarea v-model="notes" rows="5"></textarea></label><button :disabled="!dirty">保存问题与特殊需求</button><p role="status">{{dirty?'尚有未保存修改':'当前记录已保存'}}</p></fieldset></form>
<form v-if="can('recordAppliedTreatment')" @submit.prevent="record"><fieldset :disabled="busy || unknown || context.appointment.status!=='IN_PROGRESS'"><legend>记录本人已实施治疗</legend><label>实际治疗项目<select v-model="treatment" required><option value="" disabled>选择已实施项目</option><option v-for="item in catalog" :key="item.id" :value="item.id">{{item.label}}</option></select></label><label>标准单位数<input v-model="units" required inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"></label><label>实际实施时间（北京时间）<input v-model="performed" type="datetime-local" step="1" required></label><button>保存本人实施项目</button></fieldset></form>
<div class="table-scroll"><table><caption>本次就诊实际治疗</caption><thead><tr><th>实际治疗</th><th>实施牙医</th><th>单位数</th><th>历史单价</th><th>小计</th></tr></thead><tbody><tr v-for="row in context.applied_treatments" :key="row.applied_treatment_id"><td>{{catalog.find(c=>c.id===row.treatment_id)?.label || row.treatment_id}}<details><summary>记录标识</summary>{{row.applied_treatment_id}}</details></td><td>{{row.dentist_id===context.appointment.dentist_id?context.appointment.dentist_name:'实际实施牙医 '+row.dentist_id}}</td><td>{{row.standard_units}}</td><td>{{row.unit_price}}</td><td>{{row.subtotal}}</td></tr></tbody></table></div><p v-if="!context.applied_treatments.length" class="empty-state">尚未记录实际治疗，请先保存本人实施的项目。</p><p class="workspace-note">下一步：完成诊疗后，由收费岗位核对实际治疗费用并生成凭据。请先保存所有修改。</p><WorkspacePanel :open="completion" title="确认完成本次诊疗" @close="completion=false"><h3>{{context.appointment.patient_name}} · {{context.appointment.patient_number}}</h3><p>{{context.applied_treatments.length}} 项实际治疗；问题与特殊需求已保存。完成后记录进入只读阶段。</p><ul><li v-for="row in context.applied_treatments" :key="row.applied_treatment_id">{{catalog.find(c=>c.id===row.treatment_id)?.label}} · {{row.standard_units}} 标准单位 · {{row.subtotal}}</li></ul><button class="compact-primary" :disabled="busy||unknown||dirty||!!treatment" @click="complete">确认本次诊疗已完成</button></WorkspacePanel></section></section></template>
<style scoped>fieldset{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:20px 0;padding:18px}label{display:grid;gap:7px}input,select,textarea{padding:9px;border:1px solid #bacdc5;border-radius:5px}button{padding:10px 16px}.risk-banner{padding:20px;border-left:5px solid #bc8450;background:#fbf5eb}</style>
